#!/usr/bin/env node
// Bundle lib/p*/<slug>.mjs into one dist/dex-lib.mjs: each module becomes a namespaced IIFE, so the many `run` exports do not collide.
// Usage: node tools/bundle.mjs   (writes dist/dex-lib.mjs and dist/modules.json)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const out = [
  '// dex-lib.mjs: generated by tools/bundle.mjs from lib/p*/*.mjs. Never edit by hand.',
  '// Every module is pure: it returns {ok, ..., audit?, effects?, trace}; the caller (vault.mjs) does any writing.',
  'const LIB = {};',
];
const index = [];
const hoisted = new Set();
for (const p of fs.readdirSync(path.join(ROOT, 'lib')).filter((d) => /^p\d$/.test(d)).sort()) {
  for (const f of fs.readdirSync(path.join(ROOT, 'lib', p)).filter((x) => x.endsWith('.mjs')).sort()) {
    const slug = f.replace(/\.mjs$/, '');
    let src = fs.readFileSync(path.join(ROOT, 'lib', p, f), 'utf8').replace(/\r\n/g, '\n');
    // node: imports are hoisted to the top of the bundle (de-duplicated); anything else cannot be inlined
    src = src.replace(/^import\s[^;\n]*from\s+'(node:[^']+)';?[ \t]*\n/gm, (m) => { hoisted.add(m.trim().replace(/;?$/, ';')); return ''; });
    if (/^\s*import\s/m.test(src)) throw new Error(`${p}/${f} imports something other than a node: module; the bundle inlines pure modules only`);
    const node = (/^\/\/ node: (\S+)/m.exec(src) || [])[1] || '';
    const input = ((/^\/\/ input: (.*)$/m.exec(src) || [])[1] || '').trim();
    if (!/export\s+(async\s+)?function\s+run\b|export\s+const\s+run\b/.test(src)) throw new Error(`${p}/${f} has no run export`);
    src = src
      .replace(/^export\s+(async\s+)?function\s+/gm, '$1function ')
      .replace(/^export\s+const\s+/gm, 'const ')
      .replace(/^export\s*\{[^}]*\};?\s*$/gm, '');
    const name = `${p}/${slug}`;
    out.push(`LIB[${JSON.stringify(name)}] = (() => {\n${src.trimEnd()}\nreturn { run, node: ${JSON.stringify(node)}, input: ${JSON.stringify(input)} };\n})();`);
    index.push({ name, node, input });
  }
}
out.splice(2, 0, ...hoisted);
out.push(
  'export const modules = () => Object.keys(LIB);',
  'export const info = (name) => (LIB[name] ? { name, node: LIB[name].node, input: LIB[name].input } : null);',
  "export const run = (name, input) => { if (!LIB[name]) return { ok: false, error: 'unknown module: ' + name }; try { return LIB[name].run(input); } catch (e) { return { ok: false, error: 'module threw: ' + e.message }; } };",
  ''
);
fs.mkdirSync(path.join(ROOT, 'dist'), { recursive: true });
fs.writeFileSync(path.join(ROOT, 'dist', 'dex-lib.mjs'), out.join('\n'));
fs.writeFileSync(path.join(ROOT, 'dist', 'modules.json'), JSON.stringify(index, null, 2));
console.log(`bundled ${index.length} modules, ${Math.round(out.join('\n').length / 1024)} KB`);
